  static boolean hasProperty(int codePoint, int property) {
    return (entry(codePoint) & (property << 5)) != 0;
  }

  private static int entry(int codePoint) {
    if (codePoint < 0 || codePoint > 0x10ffff) return 0;
    int page = codePoint >>> 10;
    int low = PAGES[page];
    int high = PAGES[page + 1] + 1;
    while (low + 1 < high) {
      int middle = (low + high) >>> 1;
      if ((ENTRIES[middle] >>> 11) <= codePoint) low = middle;
      else high = middle;
    }
    return ENTRIES[low];
  }
